// DELVE first-person view renderer: composes the pieces generated by tools/build_view.py into the back page of the
// 8 bpp palette bitmap, back to front (d = 3 -> 0), only when the player moves, turns or something changes.

#ifndef DL_VIEW_H
#define DL_VIEW_H

#include <stdint.h>

#include "dl_gen.h"

namespace dl::view
{
    constexpr int rows = 4;     // d = 0..3
    constexpr int cols = 5;     // x = -2..2

    // runtime state of the edges the player changes (doors opened, locks unlocked, levers pulled)
    struct edge_state
    {
        uint8_t open[2 * dl::gen::N];   // 1 = door / lock open, bars raised; for lever walls 1 = pulled
    };

    // result of a redraw: the visible cells, used for sprites, the minimap and the "seen" marks
    struct visibility
    {
        int16_t cell[rows][cols];   // map cell or -1 when not visible
    };

    // world cell at relative (d, x) from cell `c` facing `dir`, or -1 outside the map
    [[nodiscard]] int relative_cell(int c, int dir, int d, int x);

    // Draws the 176x120 view into `page` (the back page, 240 px wide, 2 px per uint16_t).
    void draw(uint16_t* page, const dl::gen::level& lv, const edge_state& es, int cell, int dir, visibility& vis);

    // Draws the 60x60 minimap (15x15 cells at 4 px) around `cell` into `page` at (x, y). x must be even.
    void draw_minimap(uint16_t* page, int x, int y, const dl::gen::level& lv, const edge_state& es,
                      const uint8_t* seen, int cell, int dir);
}

#endif
